_CACHE: dict[tuple, QPixmap] = {}


def names() -> list[str]:
    return sorted(_PATHS)


def svg(name: str, color: str | None = None, stroke: float = 2.0) -> str:
    body = _PATHS.get(name) or _PATHS["circle"]
    return _SVG_OPEN.format(color=color or style.TEXT, width=stroke) + body + "</svg>"


def pixmap(name: str, color: str | None = None, size: int = 18, stroke: float = 2.0) -> QPixmap:
    """Pixmap nítido (2x) del icono, cacheado por nombre/color/tamaño."""
    key = (name, color or style.TEXT, size, stroke)
    cached = _CACHE.get(key)
    if cached is not None:
        return cached
    scale = 2
    pm = QPixmap(size * scale, size * scale)
    pm.fill(Qt.GlobalColor.transparent)
    renderer = QSvgRenderer(QByteArray(svg(name, color, stroke).encode()))
    painter = QPainter(pm)
    painter.setRenderHint(QPainter.RenderHint.Antialiasing)
    renderer.render(painter, QRectF(0, 0, size * scale, size * scale))
    painter.end()
    pm.setDevicePixelRatio(scale)
    if len(_CACHE) > 600:
        _CACHE.clear()
    _CACHE[key] = pm
    return pm


def icon(name: str, color: str | None = None, size: int = 18, stroke: float = 2.0) -> QIcon:
    ico = QIcon()
    ico.addPixmap(pixmap(name, color, size, stroke))
    return ico
